function fmtAgo(t, now) {
  const timeDiff = Math.abs(now - t);
  const units = ['s', 'm', 'h', 'd', 'w', 'M', 'Y'];
  let i = 0;
  while (timeDiff >= 1 && i < units.length - 1) {
    timeDiff /= 1000;
    i++;
  }
  return `${timeDiff.toFixed(0)} ${units[i]} ago`;
}
